"""Dewey Decimal Classification (DDC) Auxiliary Tables 1 through 6.

Standard auxiliary notation tables for facet synthesis in bibliographic classification:
- Table 1: Standard Subdivisions (-01 to -09)
- Table 2: Geographic Areas, Historical Periods, Persons (-1 to -9)
- Table 3: Subdivisions for the Arts, for Individual Literatures
- Table 4: Subdivisions of Individual Languages and Language Families
- Table 5: Ethnic and National Groups
- Table 6: Languages
"""

from typing import Dict, List, Optional
from dataclasses import dataclass


@dataclass
class DdcTableNotation:
    table_number: str
    notation: str
    caption: str
    scope_notes: str
    facet_type: str = "auxiliary"


DDC_AUXILIARY_TABLES: Dict[str, DdcTableNotation] = {}


def _aux(tbl: str, notat: str, cap: str, notes: str, facet: str = "auxiliary"):
    key = f"T{tbl}-{notat}"
    DDC_AUXILIARY_TABLES[key] = DdcTableNotation(
        table_number=tbl,
        notation=notat,
        caption=cap,
        scope_notes=notes,
        facet_type=facet
    )

