def lookup_ddc_auxiliary_notation(table_number: str, notation: str) -> Optional[DdcTableNotation]:
    """Look up a Dewey auxiliary notation across Tables 1 through 6."""
    key = f"T{table_number}-{notation.strip()}"
    return DDC_AUXILIARY_TABLES.get(key)


def get_table_notations_by_prefix(table_number: str, prefix: str) -> List[DdcTableNotation]:
    """Filter auxiliary notations by table and prefix code."""
    res = []
    t_prefix = f"T{table_number}-{prefix}"
    for k, v in DDC_AUXILIARY_TABLES.items():
        if k.startswith(t_prefix):
            res.append(v)
    return res
